mapper.select:
SELECT * FROM hotel_product_spec
WHERE product_id = #{productId}
ORDER BY sort ASC

mapper.update:
UPDATE hotel_product_spec
SET stock = stock - #{quantity}
WHERE id = #{specId} AND stock >= #{quantity}

UPDATE hotel_product_spec
SET stock = stock + #{quantity}
WHERE id = #{specId}

UPDATE hotel_product_spec
SET stock = stock - #{quantity}, frozen_stock = frozen_stock + #{quantity}
WHERE id = #{specId} AND stock >= #{quantity}

UPDATE hotel_product_spec
SET frozen_stock = frozen_stock - #{quantity}
WHERE id = #{specId} AND frozen_stock >= #{quantity}

UPDATE hotel_product_spec
SET stock = stock + #{quantity}, frozen_stock = frozen_stock - #{quantity}
WHERE id = #{specId} AND frozen_stock >= #{quantity}
